'use strict';
const data=window.PLANNER_DATA;
const $=id=>document.getElementById(id);
let all=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=v=>v===null?'Unavailable':(v*100).toFixed(1)+'%';
const count=v=>v.toLocaleString('en-SG');
const clock=v=>v.slice(11,19);
const dateLabel=date=>new Date(date+'T12:00:00+08:00').toLocaleDateString('en-SG',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Singapore'});
const stop=id=>esc(data.stops[id]||id)+' <span class="units">'+esc(id)+'</span>';
function thresholds(){return {delay:Number($('delay').value),queue:Number($('queue').value)};}
function classify(s){return PlannerRules.evaluate(s,thresholds());}
function services(){return Object.values(data.services[$('date').value]).map(classify).sort((a,b)=>b.reasons.length-a.reasons.length||b.s.queue-a.s.queue||(b.s.delays[0]?.minutes||0)-(a.s.delays[0]?.minutes||0)||a.s.service.localeCompare(b.s.service,undefined,{numeric:true}));}
function meter(value,kind=''){return `<span class="bar-value">${pct(value)}</span><div class="track"><div class="fill ${kind}" style="width:${Math.max(0,Math.min(100,(value||0)*100))}%"></div></div>`;}
function render(){const list=services(),priorities=list.filter(r=>r.reasons.length),available=list.reduce((n,r)=>n+r.s.available.length,0),delayed=list.reduce((n,r)=>n+r.delays.length,0),queueServices=list.filter(r=>r.s.queue>=thresholds().queue).length,critical=priorities.filter(r=>r.tier==='critical').length;
 const replayQuery=new URLSearchParams({date:$('date').value,delay:thresholds().delay,queue:thresholds().queue}); for(const id of ['replay-link','replay-watchlist'])$(id).href='replay.html?'+replayQuery; $('snapshot').textContent=dateLabel($('date').value)+' · Observations through 12:00';
 $('metrics').innerHTML=[['Services to reschedule',priorities.length,critical+' critical · '+(priorities.length-critical)+' high priority','alert','!'],['Delayed departures',delayed,'Across '+list.filter(r=>r.delays.length).length+' services','', '◷'],['High remaining queues',queueServices,'Services with ≥ '+thresholds().queue+' passengers','', '≋'],['Buses available for deployment',available,'Released & idle · 30-minute window','', '⊕']].map(m=>`<div class="metric"><div class="metric-head"><span>${m[0]}</span><span class="metric-icon" aria-hidden="true">${m[4]}</span></div><strong class="${m[3]}">${m[1]}</strong><small>${m[2]}</small></div>`).join('');
 $('priority-count').textContent=priorities.length;
 const shown=all?list:priorities;
 $('service-rows').innerHTML=shown.map(({s,reasons,tier,label})=>`<tr><td><div class="service-cell"><span class="service-code">${esc(s.service)}</span><div><b>Service ${esc(s.service)}</b><small>${s.assigned} assigned buses</small></div></div></td><td><span class="badge ${tier}">${label}</span><span class="reason">${reasons.join(' · ')||'No trigger met'}</span></td><td>${meter(s.utilization)}</td><td>${meter(s.load,'load')}</td><td><span class="queue-value ${s.queue>=thresholds().queue?'hot':''}">${count(s.queue)}</span><span class="units">passengers · peak</span></td><td class="queue-coverage"><span class="bar-value">${pct(s.queueCoverage.percentage)}</span><span class="units">${s.queueCoverage.queuedStops} / ${s.queueCoverage.observedStops} stops</span></td><td><span class="delay-value ${(s.delays[0]?.minutes||0)>=thresholds().delay?'hot':''}">${(s.delays[0]?.minutes||0).toFixed(1)} min</span><span class="units">at terminal</span></td><td><span class="available-count">${s.available.length}</span><span class="units">at 12:00 SGT</span></td><td><button class="details-button" data-service="${esc(s.service)}" aria-label="View service ${esc(s.service)} details">+</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">No services meet the current priority thresholds.</td></tr>';
 $('row-count').textContent=shown.length+' of 24 services shown';
 $('watchlist').classList.toggle('selected',!all);$('all').classList.toggle('selected',all);$('watchlist').setAttribute('aria-pressed',!all);$('all').setAttribute('aria-pressed',all);
}
function show(label,html){$('dialog-label').textContent=label;$('dialog-content').innerHTML=html;$('detail').showModal();}
function serviceDetail(service){const r=services().find(r=>r.s.service===service),s=r.s,t=thresholds();const next=[];if(r.delays.length)next.push('Review terminal departure spacing and recovery time against the delayed trips.');if(s.queue>=t.queue)next.push('Review headways at the affected stop and direction; check whether available capacity or departure timing can reduce the remaining queue.');if(s.held.length)next.push('Replan the affected duties using only vehicles with a confirmed engineering release.');if(!next.length)next.push('Keep this service under observation; no current priority trigger is met.');
 const hours=s.hours.map(h=>`<div class="hour-group"><div class="hour-bar" style="height:${h.utilization*100}%" title="${h.hour}:00 fleet utilization ${pct(h.utilization)}"></div><div class="hour-bar load" style="height:${(h.load||0)*100}%" title="${h.hour}:00 passenger load ${pct(h.load)}"></div><span class="hour-label">${h.hour.toString().padStart(2,'0')}:00</span></div>`).join('');
 const queues=s.events.map(e=>`<tr><td>${clock(e.time)}<span class="units">${esc(e.route)} · visit ${e.order}</span></td><td>${stop(e.stop)}</td><td>${e.boarded}</td><td class="hot"><b>${e.queue}</b></td><td>${e.onboard} / ${e.capacity}</td></tr>`).join('');
 const delays=s.delays.slice(0,8).map(d=>`<tr><td>${clock(d.planned)}</td><td>${clock(d.actual)}</td><td class="${d.minutes>=t.delay?'hot':''}"><b>${d.minutes.toFixed(1)} min</b></td><td>${esc(d.vehicle)}</td><td>${stop(d.stop)}</td></tr>`).join('');
 show('SERVICE EVIDENCE · '+dateLabel($('date').value),`<h2 class="dialog-title">Service ${esc(service)} <span class="badge ${r.tier}">${r.label}</span></h2><p class="dialog-subtitle">${esc(s.name)} · ${s.assigned} assigned buses · ${s.trips} departures observed by noon</p><div class="dialog-metrics"><div><strong>${pct(s.utilization)}</strong>Fleet utilization</div><div><strong>${pct(s.load)}</strong>Passenger load</div><div><strong>${s.queue}</strong>Peak queue after boarding</div><div><strong>${r.delays.length}</strong>Departures delayed ≥ ${t.delay} min</div></div><div class="recommendation"><b>Planner review</b><br>${next.join(' ')} Check crew availability, terminal turnaround and later duties before changing the schedule. These are review prompts; no dispatch change has been issued.</div><section class="evidence-section"><h3>Morning utilization &amp; passenger load</h3><div class="hour-chart" role="img" aria-label="Hourly profiles: ${esc(s.hours.map(h=>h.hour+':00 fleet '+pct(h.utilization)+', passenger load '+pct(h.load)).join('; '))}">${hours}</div><div class="chart-legend"><span><i class="swatch" style="background:#658749"></i>Fleet utilization</span><span><i class="swatch" style="background:#c1d492"></i>Passenger load</span></div></section><section class="evidence-section"><h3>Stops with queue after boarding</h3><p><b>${pct(s.queueCoverage.percentage)}</b> · ${s.queueCoverage.queuedStops} of ${s.queueCoverage.observedStops} observed boarding-stop positions had passengers remaining after at least one call. ${s.queueCoverage.observedStops} of ${s.queueCoverage.totalRouteStops} route boarding-stop positions were observed by noon.</p><p>Each direction and repeated route position is separate. Each position counts once, regardless of the number of bus visits. Any positive queue counts; the priority threshold does not change this measure. Final alighting-only terminals are excluded.</p></section><section class="evidence-section"><h3>Largest queues after boarding</h3><p>Top eight observed calls by remaining queue. Repeated passengers can appear in later observations.</p><div class="table-scroll"><table><thead><tr><th>Observed departure</th><th>Stop / cohort</th><th>Boarded</th><th>Remaining queue</th><th>Onboard / capacity</th></tr></thead><tbody>${queues||'<tr><td colspan="5">No remaining queues recorded in this window.</td></tr>'}</tbody></table></div></section><section class="evidence-section"><h3>Terminal departure delays</h3><p>Largest eight observed delays · ${r.delays.length} of ${s.trips} departures met the ${t.delay}-minute threshold.</p><div class="table-scroll"><table><thead><tr><th>Scheduled</th><th>Actual</th><th>Delay</th><th>Vehicle</th><th>Terminal</th></tr></thead><tbody>${delays}</tbody></table></div></section><section class="evidence-section"><h3>Underutilized buses available for deployment</h3><p>${s.available.length} buses have a released, idle 30-minute window at noon with qualified crew at the same terminal. Confirm the full journey duration and later duties before deploying.</p><div class="table-scroll"><table><thead><tr><th>Bus</th><th>Location</th><th>Qualified crew</th><th>Free until (SGT)</th><th>Capacity</th></tr></thead><tbody>${s.available.map(v=>`<tr><td><b>${esc(v.vehicle)}</b></td><td>${stop(v.stop)}</td><td>${esc(v.crew)}</td><td>${clock(v.freeUntil)}</td><td>${v.capacity}</td></tr>`).join('')||'<tr><td colspan="5">No buses meet the deployment availability checks at noon.</td></tr>'}</tbody></table></div></section><section class="evidence-section"><h3>Repair &amp; maintenance impact</h3><p>${s.held.length? s.held.map(h=>esc(h.vehicle)+' · '+esc(h.issue)+' · '+esc(h.id)).join('<br>'):'No repair hold linked to this service is evidenced at noon. All operating-fleet readiness records are released; the selected maintenance history is incomplete. The eight held workshop vehicles have no service assignments.'}</p></section>`);
}
$('date').innerHTML=data.dates.map(d=>`<option value="${d}" ${d==='2026-10-07'?'selected':''}>${dateLabel(d)}</option>`).join('');
const inherited=new URLSearchParams(location.search);if(data.dates.includes(inherited.get('date')))$('date').value=inherited.get('date');for(const key of ['delay','queue']){const n=Number(inherited.get(key));if(inherited.has(key)&&Number.isInteger(n)&&n>=1&&n<=(key==='delay'?120:1000))$(key).value=n;} $('date').addEventListener('change',render);
$('watchlist').addEventListener('click',()=>{all=false;render();});$('all').addEventListener('click',()=>{all=true;render();});
for(const id of ['delay','queue'])$(id).addEventListener('input',()=>{const valid=$('delay').checkValidity()&&$('queue').checkValidity()&&$('delay').value!==''&&$('queue').value!=='';$('input-error').textContent=valid?'':'Enter a positive threshold within the allowed range.';if(valid)render();});
$('service-rows').addEventListener('click',e=>{const b=e.target.closest('[data-service]');if(b)serviceDetail(b.dataset.service);});
$('close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close();}});
$('workshop').addEventListener('click',()=>show('WORKSHOP REGISTER',`<h2 class="dialog-title">Held workshop vehicles</h2><p class="dialog-subtitle">Separate from the 172 operating buses. No service assignment or confirmed release is supplied. Estimated completion does not establish availability.</p><div class="table-scroll"><table><thead><tr><th>Vehicle</th><th>Work order / issue</th><th>State</th><th>Estimated completion</th></tr></thead><tbody>${data.workshop.map(w=>`<tr><td><b>${esc(w.vehicle)}</b></td><td>${esc(w.issue)}<span class="units">${esc(w.id)}</span></td><td>${esc(w.status)}<span class="units">Held · release unconfirmed</span></td><td>${dateLabel(w.expectedCompletion.slice(0,10))}<span class="units">${clock(w.expectedCompletion)} SGT · estimate only</span></td></tr>`).join('')}</tbody></table></div>`));
$('methodology').addEventListener('click',()=>show('DATA & CALCULATIONS',`<div class="method"><h2 class="dialog-title">Read the evidence in context</h2><p>All performance and fleet records are fictional LionLink exercise data. Public Singapore service geography does not make this an assessment of a real operator. This dashboard is a historical, retrospective morning snapshot, not a live feed.</p><ul><li><b>Window:</b> 06:00–12:00 SGT on the selected date. Ten supplied weekdays cover 5–16 October 2026, including fictional dates after today.</li><li><b>Departure delay:</b> positive actual minus scheduled terminal departure, for trips departed by noon. Missing departures must not be read as on time.</li><li><b>Fleet utilization:</b> ${data.definitions.fleet} Actual journey intervals are clipped to the window; workshop buses are excluded. This measures in-service time, not distance or availability.</li><li><b>Underutilized / available buses:</b> ${data.definitions.available} Low average utilization alone does not establish deployment availability. Qualified crew are checked for the bus’s currently assigned service.</li><li><b>Passenger load:</b> ${data.definitions.load} This is a weighted occupancy measure, not unique passengers or a time-weighted journey load.</li><li><b>Queue:</b> ${data.definitions.queue} Service-direction and route-position cohorts remain distinct, including repeated physical stops. No capacity cause or individual waiting time is inferred.</li><li><b>Stops with queue after boarding:</b> ${data.definitions.queueCoverage}</li><li><b>Repair impact:</b> a work order must overlap the snapshot and map to an assigned service. Historic repairs already released and repairs opened after noon do not trigger morning rescheduling. The repair handout covers selected vehicles only.</li><li><b>Priority:</b> any trigger gives High priority; two or three give Critical. Sort by number of triggers, then maximum remaining queue, then maximum departure delay. The default 5-minute and 30-passenger thresholds are planner assumptions.</li></ul><p><b>Sources:</b> LionLink trips.csv, stop_calls.csv, vehicles.csv, routes.csv, vehicle_readiness.csv, crew_duties.csv, terminal_movements.csv, workshop/workshop_work_orders.csv; selected repair history from Data/01_maintenance_and_repairs.xlsx, using the existing workspace extract. Data are aggregated directly from dated operating records, so values can differ from the workbook's full-cohort summaries.</p></div>`));
render();
